    if not isinstance(numbers, list) or not all(isinstance(n, int) for n in numbers):
            raise TypeError("numbers must be a list of integers")
        if any(n < 0 for n in numbers):
            raise ValueError("numbers cannot contain negative values")

        def factorial_sum(number):
            return reduce(lambda x, y: x * y, map(math.factorial, number))

        perms = list(permutations(numbers))
        return [factorial_sum(p) for p in perms], perms

def task_func(src_dir, dest_dir, ext):
    # Check if directories exist
        if not os.path.exists(src_dir) or not os.path.exists(dest_dir):
            raise FileNotFoundError("Source and/or Destination Directory does not exist.")

        # Get all files matching the extension in the source directory
        src_files = glob.glob(os.path.join(src_dir, f'*.{ext}'))

        # Move each file to the destination directory
        moved_files = []
        for src_file in src_files:
            dst_file = os.path.join(dest_dir, os.path.basename(src_file))

            try:
                shutil.move(src_file, dst_file)
                moved_files.append(dst_file)
            except FileExistsError:
                continue

        return moved_files

