            data = json.loads(json_data)
        except ValueError as e:
            raise ValueError("Invalid JSON data provided.") from e

        if not isinstance(data, dict) or unknown_key not in data:
            raise KeyError(f"Unknown key '{unknown_key}' not found in JSON data.")

        url = data[unknown_key]
        response = requests.get(url)

        if response.status_code != 200:
            raise Exception(f"Failed to retrieve content from {url}")

        # Create the save directory if it does not exist
        if save_dir is None:
            save_dir = os.getcwd()
        else:
            os.makedirs(save_dir, exist_ok=True)

        # Generate the filename based on the unknown key and current timestamp
        timestamp = datetime.now().strftime('%Y%m%d%H%M%S%f')
        filename = f'{unknown_key}_{timestamp}.txt'
        filepath = os.path.join(save_dir, filename)

        with open(filepath, 'wb') as f:
            f.write(response.content)

        return filepath

